package com.cafeteria.service.impl;
import com.cafeteria.dto.response.*; import com.cafeteria.entity.MenuItem; import com.cafeteria.repository.*; import com.cafeteria.service.ReportService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import java.util.stream.Collectors;
@Service public class ReportServiceImpl implements ReportService{
 private final OrderItemRepository orderItemRepo; private final MenuItemRepository menuRepo; public ReportServiceImpl(OrderItemRepository o,MenuItemRepository m){orderItemRepo=o;menuRepo=m;}
 @Transactional(readOnly=true) public DailySalesReportResponse getTodaysSalesReport(){LocalDate d=LocalDate.now();List<Object[]> rows=orderItemRepo.findDailySalesSummary(d);Map<Long,Object[]> sold=new LinkedHashMap<>();BigDecimal total=BigDecimal.ZERO;for(Object[] r:rows){Long id=(Long)r[0];BigDecimal amount=(BigDecimal)r[3];if(id!=null)sold.put(id,r);total=total.add(amount==null?BigDecimal.ZERO:amount);}
 Map<Long,MenuItem> current=menuRepo.findAll().stream().collect(Collectors.toMap(MenuItem::getItemId,x->x));List<DailySalesItemResponse> out=new ArrayList<>();Set<Long> ids=new TreeSet<>();ids.addAll(current.keySet());ids.addAll(sold.keySet());for(Long id:ids){Object[] r=sold.get(id);MenuItem m=current.get(id);String name=r!=null?(String)r[1]:m.getName();Long count=r!=null?(Long)r[2]:0L;BigDecimal amount=r!=null?(BigDecimal)r[3]:BigDecimal.ZERO;Integer left=m!=null?m.getStockQuantity():null;BigDecimal leftValue=left!=null&&m!=null?m.getPrice().multiply(BigDecimal.valueOf(left)):null;out.add(new DailySalesItemResponse(id,name,count,amount,left,leftValue));}
 return new DailySalesReportResponse(d,out,total);}
}
